import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1787052895000}`),a={name:`reference/changelog.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><h2 id="_0-1-2-2026-08-18" tabindex="-1"><a href="https://github.com/ni-c/linkwarden-mcp/compare/v0.1.1...v0.1.2" target="_blank" rel="noreferrer">0.1.2</a> - 2026-08-18 <a class="header-anchor" href="#_0-1-2-2026-08-18" aria-label="Permalink to “0.1.2 - 2026-08-18”">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The architecture diagram no longer depends on the reader&#39;s operating system. It carried a <code>prefers-color-scheme</code> block, which resolves against the OS rather than the theme toggle of GitHub or npm — so dark-mode readers on a light OS got the light artwork on a dark page. The README now uses <code>&lt;picture&gt;</code>, which is resolved against the page, and the <code>&lt;img&gt;</code> that npm falls back to brings its own card instead of a media query.</li><li>The README embedded the diagram and the demo GIF with repo-relative paths, which npm does not resolve — neither image appeared on the package page. Both are absolute now.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The diagram is generated from a single source, <code>docs/assets/architecture.source.svg</code>, by <code>npm run assets</code>. The four rendered copies had already drifted apart; CI now fails if one of them is edited by hand.</li><li><code>docs/public/og.png</code> is generated at exactly 1280x640, GitHub&#39;s recommended size for a social preview, instead of being drawn by hand.</li><li>The demo recording is shown on the documentation home page as well, not only in the README, and is pinned to the content column so its width no longer depends on what the vhs tape happened to record.</li></ul><h2 id="_0-1-1-2026-08-17" tabindex="-1"><a href="https://github.com/ni-c/linkwarden-mcp/compare/v0.1.0...v0.1.1" target="_blank" rel="noreferrer">0.1.1</a> - 2026-08-17 <a class="header-anchor" href="#_0-1-1-2026-08-17" aria-label="Permalink to “0.1.1 - 2026-08-17”">​</a></h2><p>First release published by the automated pipeline, with npm provenance.</p><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li>Multi-arch container image on GHCR (<code>ghcr.io/ni-c/linkwarden-mcp</code>) for linux/amd64 and linux/arm64, built with an SBOM and build provenance.</li><li>Documentation site at <a href="https://linkwarden-mcp.ni-c.de" target="_blank" rel="noreferrer">https://linkwarden-mcp.ni-c.de</a>, including a complete tool reference generated from the registered tools — CI fails when the committed reference no longer matches the code.</li><li>Listed in the official MCP registry as <code>io.github.ni-c/linkwarden-mcp</code>.</li><li><code>CONTRIBUTING.md</code> and issue forms.</li></ul><h2 id="_0-1-0-2026-08-17" tabindex="-1"><a href="https://github.com/ni-c/linkwarden-mcp/releases/tag/v0.1.0" target="_blank" rel="noreferrer">0.1.0</a> - 2026-08-17 <a class="header-anchor" href="#_0-1-0-2026-08-17" aria-label="Permalink to “0.1.0 - 2026-08-17”">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li>Initial implementation: 28 tools for Linkwarden, split into 11 read tools that are always registered and 17 write tools that <code>LINKWARDEN_READ_ONLY=true</code> leaves out entirely.</li><li><code>get_link_content</code> reads the article text Linkwarden extracted when it preserved a page, so a saved bookmark can be summarised or quoted without fetching the live site again. Long articles are sliced and every truncation names the follow-up call. Only the readable format is served — the screenshot, PDF and single-file HTML archives are binary or raw markup.</li><li><code>search_links</code> documents Linkwarden&#39;s field-filter syntax (<code>tag:</code>, <code>collection:</code>, <code>pinned:</code>, <code>before:</code>, <code>after:</code>, <code>!</code> for negation) in its tool description, and maps readable sort names onto the integer enum the API expects. The description states that those filters need Meilisearch, and a query that uses one gets a note saying so — Linkwarden parses field filters only in its Meilisearch branch, and without it the whole query is matched as a single literal substring, so <code>tag:news</code> looks for those nine characters and quietly finds nothing. The <code>collection_id</code>, <code>tag_id</code> and <code>pinned_only</code> arguments are applied by the database and work either way.</li><li>Sort orders and archived formats are exposed as names rather than as the integers Linkwarden uses on the wire.</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h3><ul><li>URLs handed to Linkwarden must be <code>http://</code> or <code>https://</code>. Zod&#39;s <code>.url()</code> only checks that the value parses, so it accepts <code>javascript:</code>, <code>file:</code>, <code>data:</code> and <code>ftp:</code> too — and Linkwarden opens whatever it is given in its headless-browser preserver, which <code>get_link_content</code> then reads back. Without the scheme check, a model acting on an instruction injected into a preserved page could have bookmarked <code>file:///etc/passwd</code> and read the result, entirely through valid tool calls.</li><li>The access token is removed from the environment before any branch of the configuration parser, not only on the fully-configured path. &quot;URL missing or malformed&quot; is exactly the state in which someone attaches an inspector or trips a crash reporter, and the server keeps running in it.</li><li>A malformed <code>LINKWARDEN_URL</code> is no longer echoed into the log. That branch fires precisely when the variable does not hold what was expected — a token pasted into the wrong variable would otherwise be printed verbatim.</li><li>Oversized results drop whole items instead of slicing the serialized JSON. Slicing produced a document cut off mid-string and, because <code>notes</code> and <code>next_cursor</code> are serialized last, discarded the pagination hint first — the one piece of information needed to recover from the truncation.</li><li>Per-field caps on titles, URLs and descriptions. The count limits bound how many records come back and the total budget bounds the whole result, but neither bounded a single record: one bookmark with a 200 kB description could crowd out everything else.</li><li>Response bodies are read against an 8 MB ceiling, checked both from <code>content-length</code> and while streaming. The result budgets only apply once a body is already in memory.</li><li><code>bulk_update_links</code> reports ids and a count instead of forwarding Linkwarden&#39;s raw response, so it no longer bypasses the output allowlist.</li><li>Destructive tools require a server-generated, single-use confirmation token bound to the exact target, never a boolean argument. Set-valued operations bind the token to a sha256 fingerprint of the sorted id set, so a confirmation for <code>[1, 2]</code> cannot execute <code>[1, 2, 3]</code>, and <code>bulk_update_links</code> and <code>merge_tags</code> additionally bind it to the change itself — a confirmation for &quot;add one tag&quot; cannot be replayed as &quot;replace all tags with nothing&quot;.</li><li>Two non-deletions are treated as destructive because they lose data just as irreversibly: publishing a collection (<code>update_collection</code> with <code>is_public=true</code>) widens visibility to anyone with the URL, and changing a link&#39;s URL makes Linkwarden delete every preserved copy of the old page.</li><li>Confirmation prompts contain only counts, ids and flags. Titles, URLs, descriptions and collection names come from saved pages and from other users of the instance, and that text is read by a model.</li><li>Output is an explicit allowlist rather than a pass-through of Linkwarden&#39;s Prisma rows. This keeps <code>textContent</code> — the full article text of every link — out of list results, and drops the member names and avatars the collection routes include.</li><li>Partial updates read the current record and merge before writing. Linkwarden&#39;s update routes are replacements: <code>PUT /links/{id}</code> applies tags with <code>set: []</code> first and writes <code>name</code>/<code>description</code> as <code>data.name || &quot;&quot;</code>, and <code>PUT /collections/{id}</code> deletes every membership row before recreating it from the request body. An incomplete body would silently strip a link&#39;s tags or a collection&#39;s collaborators.</li><li>Mutation responses are screened instead of trusted. Several Linkwarden routes report failures with HTTP 200 and an error sentence in the body — <code>PUT /links/{id}/archive</code> answers <code>{&quot;response&quot;:&quot;Invalid URL.&quot;}</code> that way — and a Next.js route with no branch for the HTTP method used falls through to a 200 with an empty body. Both are surfaced as errors.</li><li><code>redirect: &#39;error&#39;</code> on every request. Linkwarden is commonly deployed behind a reverse proxy that redirects http to https, so a mistyped <code>LINKWARDEN_URL</code> would otherwise replay the bearer token to the redirect target. A URL that already carries the <code>/api/v1</code> prefix is normalised rather than left to 308.</li><li>The token is deleted from <code>process.env</code> after the configuration is read, a URL containing credentials or a non-http scheme exits, and a token that does not look like a Linkwarden JWT produces a warning before the first 401.</li><li><code>LINKWARDEN_INSECURE_TLS</code> is a scoped undici dispatcher, never <code>NODE_TLS_REJECT_UNAUTHORIZED</code>.</li><li>Preserved article text and all bookmark metadata are returned marked as untrusted content.</li><li>Error bodies are truncated at 2000 characters and HTML error pages from proxies are dropped entirely.</li><li>The container image deletes the npm and corepack that ship inside <code>node:24-alpine</code>. The entrypoint is plain <code>node</code>, so neither is used at runtime, and the packages they bundle were the only source of HIGH/CRITICAL findings in the image.</li></ul><p>Per-release notes, with the same content, are on the <a href="https://github.com/ni-c/linkwarden-mcp/releases" target="_blank" rel="noreferrer">releases page</a>.</p>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};